import json
def bands(n, gl):
    """runs of non-gridline indices between gridline positions"""
    runs=[]; s=None
    for i in range(n):
        if i in gl:
            if s is not None: runs.append((s,i-1)); s=None
        else:
            if s is None: s=i
    if s is not None: runs.append((s,n-1))
    return runs

def bidx(runs):
    d={}
    for k,(a,b) in enumerate(runs):
        for i in range(a,b+1): d[i]=k
    return d

def draw_edge(blk, bi1,bj1,bi2,bj2, color):
    if bi1==bi2:
        for j in range(min(bj1,bj2),max(bj1,bj2)+1): blk.setdefault((bi1,j),set()).add(color)
    elif bj1==bj2:
        for i in range(min(bi1,bi2),max(bi1,bi2)+1): blk.setdefault((i,bj1),set()).add(color)
    else:  # L path
        for j in range(min(bj1,bj2),max(bj1,bj2)+1): blk.setdefault((bi1,j),set()).add(color)
        for i in range(min(bi1,bi2),max(bi1,bi2)+1): blk.setdefault((i,bj2),set()).add(color)

def fill_bands(grid):
    h,w=len(grid),len(grid[0])
    gr={i for i in range(h) if set(grid[i])=={8}}
    gc={j for j in range(w) if len({grid[i][j] for i in range(h)})==1 and grid[0][j]==8}
    rb,cb=bands(h,gr),bands(w,gc)
    rib,cib=bidx(rb),bidx(cb)
    from collections import defaultdict
    marks=defaultdict(list)
    for i in range(h):
        for j in range(w):
            v=grid[i][j]
            if v not in (0,8): marks[v].append((rib[i],cib[j]))
    blk={}
    for color,ms in marks.items():
        if len(ms)==1:
            blk.setdefault(ms[0],set()).add(color); continue
        # Kruskal MST on rectilinear distance
        edges=sorted(((abs(a[0]-b[0])+abs(a[1]-b[1]),a,b) for i,a in enumerate(ms) for b in ms[i+1:]))
        parent={m:m for m in ms}
        def find(x):
            while parent[x]!=x: parent[x]=parent[parent[x]]; x=parent[x]
            return x
        cnt=0
        for d,a,b in edges:
            ra,rb_=find(a),find(b)
            if ra!=rb_:
                parent[ra]=rb_; draw_edge(blk,*a,*b,color); cnt+=1
                if cnt==len(ms)-1: break
    out=[row[:] for row in grid]
    for (bi,bj),cols in blk.items():
        val=6 if len(cols)>1 else cols.pop()
        for i in range(rb[bi][0],rb[bi][1]+1):
            for j in range(cb[bj][0],cb[bj][1]+1):
                out[i][j]=val
    return out

